after:
@import "./palaver/styles/tokens.css";

* {
  box-sizing: border-box;
}

html,
body,
#root {
  min-height: 100%;
  margin: 0;
}

body {
  background:
    radial-gradient(circle at 20% 10%, rgba(157, 184, 255, 0.13), transparent 30%),
    radial-gradient(circle at 80% 20%, rgba(233, 221, 196, 0.11), transparent 32%),
    linear-gradient(135deg, #030405, #080a0d 48%, #050607);
  color: var(--text);
  overflow: hidden;
}

button,
textarea,
input {
  font: inherit;
}

button {
  color: var(--text);
  cursor: pointer;
}

.ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    linear-gradient(rgba(255,255,255,0.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.014) 1px, transparent 1px);
  background-size: 54px 54px;
}

.ambient::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, transparent, rgba(0,0,0,.72));
}

.aurora {
  position: absolute;
  width: 52vw;
  height: 52vw;
  border-radius: 999px;
  filter: blur(80px);
  opacity: 0.22;
  mix-blend-mode: screen;
}

.a1 {
  left: -14vw;
  top: -18vw;
  background: rgba(157, 184, 255, 0.32);
  animation: drift 18s ease-in-out infinite;
}

.a2 {
  right: -18vw;
  top: 8vh;
  background: rgba(233, 221, 196, 0.22);
  animation: drift 24s ease-in-out infinite reverse;
}

.a3 {
  left: 32vw;
  bottom: -24vw;
  background: rgba(145, 242, 189, 0.11);
  animation: drift 28s ease-in-out infinite;
}

@keyframes drift {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  50% { transform: translate3d(4vw, -2vh, 0) scale(1.12); }
}

.topology {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0.9;
}

.topology path {
  fill: none;
  stroke: rgba(245,247,250,.35);
  stroke-width: 1;
}

.particle {
  position: absolute;
  border-radius: 999px;
  background: rgba(255,255,255,.7);
  box-shadow: 0 0 18px rgba(157,184,255,.5);
}

.app {
  position: relative;
  z-index: 1;
  height: 100vh;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.top {
  height: 76px;
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 18px;
  align-items: center;
  padding: 14px 18px;
  border: 1px solid var(--line);
  border-radius: 28px;
  background: rgba(10, 12, 16, 0.64);
  backdrop-filter: var(--blur);
  box-shadow: var(--shadow);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.logo {
  width: 42px;
  height: 42px;
  border-radius: 15px;
  display: grid;
  place-items: center;
  color: #090a0c;
  background:
    radial-gradient(circle at 25% 20%, #fff, var(--accent) 52%, #a58f65);
  box-shadow:
    0 0 0 1px rgba(255,255,255,.24) inset,
    0 18px 40px rgba(233,221,196,.16);
  font-weight: 900;
  letter-spacing: -0.08em;
}

.brand h1 {
  margin: 0;
  font-size: 18px;
  letter-spacing: -0.04em;
  line-height: 1;
}

.brand p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 12px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

nav {
  display: flex;
  gap: 8px;
  padding: 6px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,.035);
}

nav button,
.button-grid button,
.composer button,
.palette-actions button {
  border: 1px solid var(--line);
  background: rgba(255,255,255,.045);
  border-radius: 999px;
  padding: 9px 12px;
  font-size: 12px;
  color: var(--muted);
  transition: .18s ease;
}

button:hover {
  border-color: var(--line2);
  color: var(--text);
  background: rgba(255,255,255,.08);
  transform: translateY(-1px);
}

button.active,
button.primary,
button.accent {
  color: #08090a;
  background: linear-gradient(135deg, #fff, var(--accent));
  border-color: rgba(255,255,255,.45);
  box-shadow: 0 12px 34px rgba(233,221,196,.16);
}

.status-pill {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 13px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,.045);
  color: var(--muted);
  font-size: 12px;
}

.pulse {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--good);
  box-shadow: 0 0 18px var(--good);
}

.pulse.thinking {
  background: var(--warn);
  box-shadow: 0 0 18px var(--warn);
}

.shell {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(285px, 0.78fr) minmax(380px, 1.08fr) minmax(370px, 1fr);
  gap: 16px;
  perspective: 1400px;
}

.panel {
  min-height: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 30px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.055), transparent 120px),
    var(--panel);
  backdrop-filter: var(--blur);
  box-shadow: var(--shadow);
}

.panel-head {
  height: 55px;
  padding: 0 17px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--line);
}

.panel-head b {
  letter-spacing: -0.03em;
}

.panel-head span {
  color: var(--faint);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .16em;
}

.panel-body {
  height: calc(100% - 55px);
  padding: 16px;
  overflow: auto;
}

.kicker {
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: .18em;
  font-size: 10px;
  margin: 4px 0 12px;
}

.manifesto {
  margin: 0 0 18px;
  font-size: clamp(22px, 2.6vw, 38px);
  line-height: .96;
  letter-spacing: -0.07em;
  font-weight: 750;
}

.button-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 14px;
}

.metric-deck {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 9px;
  margin: 14px 0;
}

.metric {
  border: 1px solid var(--line);
  background: rgba(255,255,255,.038);
  border-radius: 20px;
  padding: 12px;
}

.metric small,
.metric span {
  display: block;
  color: var(--faint);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: .13em;
}

.metric strong {
  display: block;
  margin: 5px 0;
  font-size: 21px;
  letter-spacing: -0.06em;
}

.empty-card {
  border: 1px solid var(--line);
  background: rgba(255,255,255,.034);
  border-radius: 22px;
  padding: 14px;
  color: var(--muted);
}

.empty-card span {
  color: var(--text);
  font-weight: 700;
}

.empty-card p {
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.45;
}

.subtool {
  margin-top: 14px;
}

.subtool-title {
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 12px;
  margin-bottom: 8px;
}

.tree-shell {
  max-height: 360px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 22px;
  padding: 8px;
  background: rgba(0,0,0,.18);
}

.tree-item {
  display: grid;
  grid-template-columns: 18px 1fr auto;
  gap: 6px;
  align-items: center;
  min-height: 30px;
  border-radius: 12px;
  color: var(--muted);
  font-size: 12px;
  user-select: none;
}

.tree-item:hover {
  background: rgba(255,255,255,.06);
  color: var(--text);
}

.tree-item small {
  color: var(--faint);
  font-size: 9px;
  padding-right: 8px;
}

.chat {
  display: flex;
  flex-direction: column;
}

.chat-scroll {
  flex: 1;
  min-height: 0;
  padding: 16px;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.message {
  border: 1px solid var(--line);
  border-radius: 24px;
  padding: 13px;
  background: rgba(255,255,255,.04);
}

.message.user {
  background: rgba(157,184,255,.075);
}

.message-meta {
  display: flex;
  justify-content: space-between;
  color: var(--faint);
  font-size: 10px;
  letter-spacing: .14em;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.message-meta span {
  color: var(--accent);
}

.message-body {
  color: var(--text);
  white-space: pre-wrap;
  line-height: 1.55;
  font-size: 14px;
}

.composer {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 8px;
  padding: 12px;
  border-top: 1px solid var(--line);
}

.composer textarea {
  resize: none;
  height: 54px;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 14px;
  background: rgba(0,0,0,.24);
  color: var(--text);
  outline: none;
}

.composer textarea:focus,
.palette input:focus {
  border-color: rgba(233,221,196,.5);
  box-shadow: 0 0 0 4px rgba(233,221,196,.08);
}

.right {
  position: relative;
}

.workspace-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.workspace-fill {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  border-radius: 22px;
  border: 1px solid var(--line);
}

.empty-state {
  flex: 1;
  min-height: 260px;
  display: grid;
  align-content: center;
  padding: 30px;
  border: 1px solid var(--line);
  border-radius: 26px;
  background:
    radial-gradient(circle at 30% 20%, rgba(157,184,255,.12), transparent 38%),
    rgba(255,255,255,.035);
}

.empty-state span {
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: .2em;
  font-size: 11px;
}

.empty-state h1 {
  margin: 10px 0;
  font-size: clamp(38px, 5vw, 72px);
  line-height: .88;
  letter-spacing: -0.08em;
}

.empty-state p {
  max-width: 480px;
  color: var(--muted);
}

.trace {
  max-height: 155px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 22px;
  padding: 12px;
  background: rgba(0,0,0,.22);
}

.trace b {
  display: block;
  color: var(--faint);
  font-size: 10px;
  letter-spacing: .16em;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.trace pre {
  margin: 0;
  color: rgba(245,247,250,.66);
  font-size: 11px;
  white-space: pre-wrap;
}

.graph-wrap {
  flex: 1;
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: 26px;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 46%, rgba(157,184,255,.14), transparent 40%),
    rgba(0,0,0,.22);
}

.graph-toolbar {
  height: 58px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.graph-toolbar strong,
.graph-toolbar small {
  display: block;
}

.graph-toolbar small {
  color: var(--muted);
  font-size: 11px;
}

.graph-stats {
  display: flex;
  gap: 8px;
}

.graph-stats span {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 8px;
  color: var(--muted);
  font-size: 11px;
}

.graph-wrap svg {
  width: 100%;
  height: calc(100% - 58px);
}

.graph-wrap line {
  stroke: rgba(245,247,250,.34);
  stroke-width: .18;
}

.graph-wrap circle {
  fill: url(#nodeGlow);
  filter: drop-shadow(0 0 6px rgba(157,184,255,.55));
}

.timeline {
  flex: 1;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 24px;
  padding: 14px;
  background: rgba(0,0,0,.18);
}

.timeline-row {
  position: relative;
  padding: 0 0 16px 20px;
  border-left: 1px solid var(--line);
}

.timeline-row::before {
  content: "";
  position: absolute;
  left: -4px;
  top: 2px;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--accent);
  box-shadow: 0 0 16px rgba(233,221,196,.45);
}

.timeline-row small {
  color: var(--faint);
  font-size: 10px;
}

.timeline-row p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 12px;
}

.palette-backdrop {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: start center;
  padding-top: 11vh;
  background: rgba(0,0,0,.48);
  backdrop-filter: blur(18px);
}

.palette {
  width: min(780px, calc(100vw - 32px));
  border: 1px solid var(--line2);
  border-radius: 32px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.09), transparent 120px),
    rgba(10,12,16,.88);
  box-shadow: 0 40px 140px rgba(0,0,0,.72);
  padding: 14px;
  transform-origin: top center;
}

.palette-header {
  display: flex;
  justify-content: space-between;
  padding: 4px 6px 12px;
  color: var(--muted);
}

.palette-header strong {
  color: var(--text);
}

.palette-header span {
  color: var(--faint);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 3px 7px;
}

.palette input {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 22px;
  padding: 17px;
  background: rgba(0,0,0,.28);
  color: var(--text);
  outline: none;
  font-size: 17px;
}

.palette-results {
  margin-top: 12px;
  display: grid;
  gap: 8px;
  max-height: 370px;
  overflow: auto;
}

.palette-results button {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 14px;
  background: rgba(255,255,255,.04);
  display: flex;
  justify-content: space-between;
}

.palette-results button span {
  color: var(--text);
}

.palette-results button small {
  color: var(--faint);
  text-transform: uppercase;
  letter-spacing: .14em;
}

.palette-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

@media (max-width: 1180px) {
  body {
    overflow: auto;
  }

  .app {
    height: auto;
    min-height: 100vh;
  }

  .shell {
    grid-template-columns: 1fr;
  }

  .panel {
    min-height: 520px;
  }

  .top {
    grid-template-columns: 1fr;
    height: auto;
  }

  nav {
    overflow: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }
}

/* ===== PALAVER PHASE 2: MODE SYSTEM + OBSERVATORY ===== */

.mode-switch {
  display: flex;
  gap: 5px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255,255,255,.035);
}

.mode-switch button {
  position: relative;
  overflow: hidden;
  border: 0;
  background: transparent;
  border-radius: 999px;
  padding: 8px 11px;
  color: var(--faint);
  font-size: 11px;
}

.mode-switch button span:last-child {
  position: relative;
  z-index: 2;
}

.mode-switch button.on {
  color: #07080a;
}

.mode-glow {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, #fff, var(--accent));
  box-shadow: 0 14px 38px rgba(233,221,196,.2);
}

.workspace-chrome {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 26px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.05), transparent 90px),
    rgba(0,0,0,.2);
}

.workspace-chrome-head {
  height: 54px;
  padding: 0 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--line);
}

.workspace-chrome-head strong,
.workspace-chrome-head small {
  display: block;
}

.workspace-chrome-head strong {
  font-size: 12px;
  max-width: 420px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.workspace-chrome-head small {
  color: var(--faint);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: .15em;
  margin-top: 3px;
}

.workspace-chrome-body {
  height: calc(100% - 54px);
  min-height: 0;
}

.chrome-dots {
  display: flex;
  gap: 7px;
}

.chrome-dots span {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: rgba(255,255,255,.18);
  box-shadow: 0 0 18px rgba(255,255,255,.08);
}

.observatory {
  flex: 1;
  min-height: 0;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 26px;
  padding: 18px;
  background:
    radial-gradient(circle at 22% 10%, rgba(233,221,196,.14), transparent 34%),
    radial-gradient(circle at 80% 38%, rgba(157,184,255,.12), transparent 38%),
    rgba(0,0,0,.22);
}

.observatory-hero {
  padding: 8px 4px 20px;
}

.observatory-hero span {
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: .18em;
  font-size: 10px;
}

.observatory-hero h2 {
  margin: 10px 0;
  font-size: clamp(34px, 4.6vw, 64px);
  line-height: .88;
  letter-spacing: -.08em;
}

.observatory-hero p {
  color: var(--muted);
  max-width: 560px;
  margin: 0;
  line-height: 1.5;
}

.observatory-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 4px 0 14px;
}

.observer-card {
  position: relative;
  overflow: hidden;
  min-height: 132px;
  border: 1px solid var(--line);
  border-radius: 24px;
  padding: 16px;
  background:
    linear-gradient(145deg, rgba(255,255,255,.075), rgba(255,255,255,.025)),
    rgba(0,0,0,.18);
}

.observer-card::after {
  content: "";
  position: absolute;
  width: 120px;
  height: 120px;
  right: -50px;
  top: -50px;
  border-radius: 999px;
  background: rgba(233,221,196,.1);
  filter: blur(22px);
}

.observer-card small,
.observer-card span {
  display: block;
  color: var(--faint);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: .15em;
}

.observer-card strong {
  display: block;
  margin: 11px 0;
  font-size: 32px;
  line-height: .9;
  letter-spacing: -.07em;
}

.observer-trace {
  border: 1px solid var(--line);
  border-radius: 24px;
  padding: 14px;
  background: rgba(0,0,0,.26);
}

.observer-trace b {
  display: block;
  color: var(--accent);
  margin-bottom: 10px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: .17em;
}

.observer-trace pre {
  margin: 0;
  color: rgba(245,247,250,.62);
  white-space: pre-wrap;
  font-size: 11px;
  line-height: 1.55;
}

/* ===== PALAVER PHASE 3: SIGNAL RIBBON + CINEMATIC WORKFLOW ===== */

.intelligence-ribbon {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin-top: -4px;
}

.signal {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 10px 12px;
  background:
    linear-gradient(145deg, rgba(255,255,255,.06), rgba(255,255,255,.018)),
    rgba(0,0,0,.16);
  backdrop-filter: blur(18px);
}

.signal::before {
  content: "";
  position: absolute;
  inset: -1px;
  opacity: .42;
  background: radial-gradient(circle at 10% 0%, rgba(255,255,255,.18), transparent 35%);
  pointer-events: none;
}

.signal span {
  display: block;
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: .18em;
}

.signal b {
  display: block;
  margin-top: 4px;
  color: var(--text);
  font-size: 13px;
  letter-spacing: -.03em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.signal.good b {
  color: var(--good);
}

.signal.warn b {
  color: var(--warn);
}

.signal.dim b {
  color: var(--muted);
}

.cinematic-divider {
  position: relative;
  height: 1px;
  margin: 16px 0;
  overflow: hidden;
  background: rgba(255,255,255,.08);
}

.cinematic-divider span {
  position: absolute;
  top: 0;
  left: 0;
  width: 38%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(233,221,196,.9), transparent);
  filter: drop-shadow(0 0 12px rgba(233,221,196,.5));
}

.quick-lens {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
  margin-bottom: 14px;
}

.quick-lens button {
  position: relative;
  overflow: hidden;
  text-align: left;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 13px;
  background:
    radial-gradient(circle at 0% 0%, rgba(233,221,196,.08), transparent 36%),
    rgba(255,255,255,.034);
}

.quick-lens button::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0;
  background: linear-gradient(120deg, transparent, rgba(255,255,255,.08), transparent);
  transform: translateX(-70%);
  transition: .34s ease;
}

.quick-lens button:hover::after {
  opacity: 1;
  transform: translateX(70%);
}

.quick-lens span {
  display: block;
  color: var(--text);
  font-size: 13px;
  letter-spacing: -.02em;
}

.quick-lens small {
  display: block;
  color: var(--faint);
  margin-top: 4px;
  font-size: 11px;
}

.focus-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border: 1px solid var(--line);
  border-radius: 22px;
  padding: 12px 14px;
  background:
    linear-gradient(90deg, rgba(233,221,196,.075), transparent 32%),
    rgba(0,0,0,.18);
}

.focus-strip small {
  display: block;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: .18em;
  font-size: 9px;
  margin-bottom: 4px;
}

.focus-strip strong {
  display: block;
  max-width: 420px;
  color: var(--text);
  font-size: 13px;
  letter-spacing: -.03em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.focus-strip span {
  color: var(--faint);
  font-size: 11px;
  white-space: nowrap;
}

.panel {
  transform-style: preserve-3d;
}

.panel:hover {
  border-color: rgba(255,255,255,.14);
}

.message,
.metric,
.observer-card,
.tree-shell,
.graph-wrap,
.timeline,
.workspace-chrome,
.empty-state,
.trace {
  transition:
    border-color .22s ease,
    background .22s ease,
    transform .22s ease,
    box-shadow .22s ease;
}

.message:hover,
.metric:hover,
.observer-card:hover,
.tree-shell:hover,
.graph-wrap:hover,
.timeline:hover,
.workspace-chrome:hover,
.empty-state:hover {
  border-color: rgba(255,255,255,.15);
  box-shadow: 0 18px 60px rgba(0,0,0,.22);
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: rgba(255,255,255,.025);
}

::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,.14);
  border-radius: 999px;
  border: 3px solid rgba(0,0,0,.1);
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255,255,255,.24);
}

@media (max-width: 1180px) {
  .intelligence-ribbon {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* ===== PALAVER PHASE 4: SPATIAL DOCK + ROUTE CONSTELLATION ===== */

.spatial-dock {
  position: fixed;
  left: 18px;
  top: 50%;
  z-index: 12;
  transform: translateY(-50%);
  width: 74px;
  padding: 9px;
  display: grid;
  gap: 8px;
  border: 1px solid var(--line);
  border-radius: 26px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.07), rgba(255,255,255,.025)),
    rgba(8,10,13,.62);
  backdrop-filter: blur(24px) saturate(1.2);
  box-shadow:
    0 28px 90px rgba(0,0,0,.5),
    0 0 0 1px rgba(255,255,255,.025) inset;
}

.spatial-dock button {
  position: relative;
  overflow: hidden;
  min-height: 54px;
  border: 1px solid transparent;
  border-radius: 18px;
  background: rgba(255,255,255,.035);
  display: grid;
  place-items: center;
  gap: 2px;
  padding: 7px 4px;
}

.spatial-dock button::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0;
  background: radial-gradient(circle at 50% 0%, rgba(233,221,196,.18), transparent 60%);
  transition: .2s ease;
}

.spatial-dock button:hover::after,
.spatial-dock button.active::after {
  opacity: 1;
}

.spatial-dock button.active {
  border-color: rgba(233,221,196,.32);
  background: rgba(233,221,196,.085);
}

.spatial-dock span {
  position: relative;
  z-index: 1;
  color: var(--text);
  font-size: 18px;
  line-height: 1;
}

.spatial-dock small {
  position: relative;
  z-index: 1;
  color: var(--faint);
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.dock-separator {
  height: 1px;
  background: var(--line);
  margin: 4px 8px;
}

.route-constellation {
  margin: 14px 0;
  border: 1px solid var(--line);
  border-radius: 24px;
  padding: 12px;
  background:
    radial-gradient(circle at 20% 0%, rgba(157,184,255,.08), transparent 45%),
    rgba(0,0,0,.16);
}

.route-title {
  display: flex;
  justify-content: space-between;
  margin-bottom: 10px;
}

.route-title span {
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
}

.route-title small {
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: .13em;
}

.route-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 7px;
}

.route-grid button {
  text-align: left;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(255,255,255,.035);
  padding: 10px;
}

.route-grid b {
  display: block;
  color: var(--text);
  font-size: 12px;
  letter-spacing: -.02em;
}

.route-grid code {
  display: block;
  color: var(--faint);
  font-size: 10px;
  margin-top: 4px;
}

.layered-backdrop-card {
  position: absolute;
  right: 30px;
  bottom: 24px;
  width: 180px;
  height: 180px;
  opacity: .72;
  pointer-events: none;
}

.empty-state {
  position: relative;
  overflow: hidden;
}

.orbital-ring {
  position: absolute;
  inset: 18px;
  border-radius: 999px;
  border: 1px solid rgba(233,221,196,.16);
}

.orbital-ring::before {
  content: "";
  position: absolute;
  left: 50%;
  top: -4px;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: rgba(233,221,196,.95);
  box-shadow: 0 0 24px rgba(233,221,196,.55);
}

.orbital-ring.r2 {
  inset: 42px;
  border-color: rgba(157,184,255,.14);
  transform: rotate(40deg);
}

.orbital-ring.r2::before {
  background: rgba(157,184,255,.95);
  box-shadow: 0 0 24px rgba(157,184,255,.55);
}

.orbital-core {
  position: absolute;
  inset: 72px;
  border-radius: 999px;
  background:
    radial-gradient(circle, rgba(255,255,255,.9), rgba(233,221,196,.22) 48%, transparent 70%);
  filter: blur(.2px);
}

@media (max-width: 1180px) {
  .spatial-dock {
    display: none;
  }
}

@media (min-width: 1181px) {
  .app {
    padding-left: 106px;
  }
}

/* ===== PALAVER PHASE 5: NEURAL SEARCH + AUTHORITY VISUAL STACK ===== */

.neural-backdrop {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: grid;
  place-items: start center;
  padding-top: 8vh;
  background:
    radial-gradient(circle at 50% 0%, rgba(233,221,196,.12), transparent 36%),
    rgba(0,0,0,.58);
  backdrop-filter: blur(22px) saturate(1.1);
}

.neural-search {
  width: min(940px, calc(100vw - 32px));
  max-height: 84vh;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 34px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.09), transparent 160px),
    radial-gradient(circle at 10% 0%, rgba(233,221,196,.1), transparent 32%),
    rgba(9,11,15,.91);
  box-shadow:
    0 50px 160px rgba(0,0,0,.72),
    0 0 0 1px rgba(255,255,255,.04) inset;
  transform-origin: top center;
}

.neural-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  padding: 18px;
  border-bottom: 1px solid var(--line);
}

.neural-head span {
  display: block;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: .18em;
  font-size: 10px;
  margin-bottom: 8px;
}

.neural-head strong {
  display: block;
  font-size: clamp(28px, 4vw, 54px);
  line-height: .9;
  letter-spacing: -.08em;
}

.neural-head button {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 8px 10px;
  background: rgba(255,255,255,.045);
  color: var(--muted);
}

.neural-input-shell {
  margin: 16px;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 12px;
  align-items: center;
  border: 1px solid var(--line2);
  border-radius: 24px;
  padding: 0 16px;
  background: rgba(0,0,0,.28);
}

.neural-input-shell span {
  color: var(--accent);
  font-size: 20px;
}

.neural-input-shell input {
  height: 64px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 19px;
}

.scope-tabs {
  display: flex;
  gap: 8px;
  padding: 0 16px 14px;
  overflow: auto;
}

.scope-tabs button {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 12px;
  background: rgba(255,255,255,.035);
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .12em;
}

.scope-tabs button.on {
  background: linear-gradient(135deg, #fff, var(--accent));
  color: #07080a;
}

.neural-results {
  max-height: 430px;
  overflow: auto;
  padding: 0 16px 16px;
  display: grid;
  gap: 9px;
}

.neural-results button {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 16px;
  text-align: left;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 22px;
  padding: 15px;
  background:
    linear-gradient(120deg, rgba(255,255,255,.055), rgba(255,255,255,.02)),
    rgba(0,0,0,.14);
}

.neural-results b {
  display: block;
  color: var(--text);
  font-size: 14px;
  letter-spacing: -.03em;
}

.neural-results p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.neural-results small {
  color: var(--faint);
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: 10px;
}

.system-marquee {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(0,0,0,.18);
  margin-bottom: 14px;
  mask-image: linear-gradient(90deg, transparent, black 12%, black 88%, transparent);
}

.system-marquee div {
  display: flex;
  width: max-content;
}

.system-marquee span {
  display: inline-block;
  padding: 8px 16px;
  color: var(--faint);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: .18em;
}

.authority-preview-stack {
  display: grid;
  gap: 8px;
  margin: 14px 0;
}

.authority-preview {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 11px;
  background:
    radial-gradient(circle at 0% 50%, rgba(233,221,196,.08), transparent 44%),
    rgba(255,255,255,.032);
}

.authority-preview > span {
  width: 34px;
  height: 34px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  background: rgba(233,221,196,.08);
  color: var(--accent);
  font-size: 10px;
  border: 1px solid rgba(233,221,196,.16);
}

.authority-preview b,
.authority-preview small {
  display: block;
}

.authority-preview b {
  color: var(--text);
  font-size: 12px;
  letter-spacing: -.02em;
}

.authority-preview small {
  color: var(--faint);
  font-size: 10px;
  margin-top: 3px;
}

@media (max-width: 720px) {
  .neural-head strong {
    font-size: 30px;
  }

  .neural-results button {
    grid-template-columns: 1fr;
  }
}

