/* ===== PALAVER PHASE 6: FLAGSHIP GRAPH ENVIRONMENT ===== */

.graph-flagship {
  min-height: 560px;
}

.graph-stage {
  height: calc(100% - 58px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) 245px;
  gap: 0;
}

.graph-canvas-shell {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 50%, rgba(157,184,255,.12), transparent 34%),
    radial-gradient(circle at 20% 22%, rgba(233,221,196,.08), transparent 30%),
    linear-gradient(rgba(255,255,255,.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.014) 1px, transparent 1px);
  background-size: auto, auto, 34px 34px, 34px 34px;
}

.graph-canvas-shell::before {
  content: "";
  position: absolute;
  inset: 8%;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255,255,255,.05), transparent 58%);
  filter: blur(18px);
  pointer-events: none;
}

.graph-canvas-shell svg {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
}

.graph-flagship line {
  stroke: rgba(233,221,196,.34);
  stroke-width: .16;
  filter: drop-shadow(0 0 4px rgba(233,221,196,.18));
}

.graph-flagship circle:not(.node-halo) {
  fill: url(#nodeGlow);
  filter: drop-shadow(0 0 7px rgba(157,184,255,.58));
}

.node-halo {
  fill: rgba(157,184,255,.2);
}

.graph-sidecar {
  border-left: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(255,255,255,.055), transparent 100px),
    rgba(0,0,0,.16);
  padding: 12px;
  overflow: auto;
}

.graph-intelligence {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 12px;
}

.graph-intel-card {
  min-height: 78px;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 10px;
  background:
    radial-gradient(circle at 0% 0%, rgba(233,221,196,.09), transparent 50%),
    rgba(255,255,255,.035);
}

.graph-intel-card span {
  display: block;
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: .15em;
}

.graph-intel-card b {
  display: block;
  margin-top: 8px;
  color: var(--text);
  font-size: 21px;
  letter-spacing: -.06em;
}

.graph-inspector-rail {
  border: 1px solid var(--line);
  border-radius: 22px;
  overflow: hidden;
  background: rgba(0,0,0,.18);
}

.graph-inspector-title {
  padding: 12px;
  border-bottom: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.graph-inspector-title span {
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
}

.graph-inspector-title small {
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: .12em;
}

.graph-node-list {
  padding: 8px;
  display: grid;
  gap: 6px;
}

.graph-node-list p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  padding: 8px;
}

.graph-node-row {
  display: grid;
  grid-template-columns: 30px 1fr;
  gap: 8px;
  align-items: center;
  min-height: 34px;
  border: 1px solid transparent;
  border-radius: 14px;
  padding: 6px;
  background: rgba(255,255,255,.025);
}

.graph-node-row:hover {
  border-color: var(--line);
  background: rgba(255,255,255,.055);
}

.graph-node-row span {
  width: 24px;
  height: 24px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  color: var(--accent);
  font-size: 9px;
  background: rgba(233,221,196,.075);
  border: 1px solid rgba(233,221,196,.12);
}

.graph-node-row b {
  min-width: 0;
  color: var(--muted);
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

@media (max-width: 920px) {
  .graph-stage {
    grid-template-columns: 1fr;
  }

  .graph-sidecar {
    border-left: 0;
    border-top: 1px solid var(--line);
  }
}

/* ===== PALAVER PHASE 7: REPOSITORY INTELLIGENCE SURFACE ===== */

.repo-intelligence {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 12px 0;
}

.repo-intel-card {
  min-height: 76px;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 11px;
  background:
    radial-gradient(circle at 0% 0%, rgba(157,184,255,.08), transparent 50%),
    rgba(255,255,255,.033);
}

.repo-intel-card span {
  display: block;
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: .15em;
}

.repo-intel-card b {
  display: block;
  margin-top: 8px;
  color: var(--text);
  font-size: 22px;
  letter-spacing: -.06em;
}

.repo-focus-board {
  margin: 12px 0;
  border: 1px solid var(--line);
  border-radius: 24px;
  overflow: hidden;
  background:
    radial-gradient(circle at 12% 0%, rgba(233,221,196,.08), transparent 42%),
    rgba(0,0,0,.16);
}

.repo-focus-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 14px;
  padding: 14px;
  border-bottom: 1px solid var(--line);
}

.repo-focus-head span {
  display: block;
  color: var(--accent);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: .18em;
  margin-bottom: 6px;
}

.repo-focus-head strong {
  display: block;
  color: var(--text);
  font-size: 17px;
  line-height: .98;
  letter-spacing: -.05em;
}

.repo-focus-head small {
  color: var(--faint);
  font-size: 10px;
  white-space: nowrap;
  text-transform: uppercase;
  letter-spacing: .12em;
}

.repo-focus-grid {
  max-height: 330px;
  overflow: auto;
  padding: 10px;
  display: grid;
  gap: 8px;
}

.repo-focus-grid button {
  width: 100%;
  display: grid;
  grid-template-columns: 34px 1fr;
  grid-template-areas:
    "num title"
    "num path";
  gap: 3px 9px;
  text-align: left;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 17px;
  padding: 10px;
  background:
    linear-gradient(120deg, rgba(255,255,255,.05), rgba(255,255,255,.02)),
    rgba(0,0,0,.12);
}

.repo-focus-grid button > span {
  grid-area: num;
  width: 30px;
  height: 30px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  color: var(--accent);
  background: rgba(233,221,196,.075);
  border: 1px solid rgba(233,221,196,.14);
  font-size: 10px;
}

.repo-focus-grid b {
  grid-area: title;
  min-width: 0;
  color: var(--text);
  font-size: 12px;
  letter-spacing: -.02em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.repo-focus-grid small {
  grid-area: path;
  min-width: 0;
  color: var(--faint);
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

