}

.personality-card-head b {
  color: var(--text);
  font-size: 13px;
}

.personality-card-head small {
  color: var(--faint);
  text-transform: uppercase;
  letter-spacing: .13em;
  font-size: 9px;
}

.personality-card pre {
  margin: 0;
  max-height: 360px;
  overflow: auto;
  color: rgba(245,247,250,.62);
  font-size: 11px;
  line-height: 1.5;
  white-space: pre-wrap;
}

.council-stack {
  display: grid;
  gap: 8px;
}

.council-stack p {
  color: var(--muted);
  margin: 0;
}

.council-row {
  display: grid;
  grid-template-columns: 42px 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 10px;
  background: rgba(255,255,255,.032);
}

.council-row > span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: rgba(233,221,196,.075);
  color: var(--accent);
  border: 1px solid rgba(233,221,196,.14);
  font-size: 10px;
}

.council-row b,
.council-row small {
  display: block;
}

.council-row b {
  color: var(--text);
