  line-height: .9;
  letter-spacing: -.08em;
}

.identity-metrics span {
  display: block;
  color: var(--muted);
  margin: 8px 0 14px;
}

.genome-bars {
  display: grid;
  gap: 10px;
}

.genome-bar > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 5px;
}

.genome-bar span {
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .1em;
}

.genome-bar small {
  color: var(--accent);
}

.bar-track {
  height: 7px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255,255,255,.07);
}

.bar-track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(157,184,255,.72), rgba(233,221,196,.92));
  box-shadow: 0 0 18px rgba(233,221,196,.2);
}

.prompt-card pre {
  max-height: 520px;
}

@media (max-width: 920px) {
  .personality-grid {
    grid-template-columns: 1fr;
  }
}

